-- 1 przypadek u¿ycia bazy danych -------> Grupowanie
CREATE VIEW perspektywa_1 AS
SELECT METODA_P£ATNOŒCI, SUM(KWOTA) AS SUMA_KWOTA
FROM P£ATNOŒCI
GROUP BY METODA_P£ATNOŒCI;

-- 2 przypadek u¿ycia bazy danych -----> Sortowanie
CREATE VIEW perspektywa_2 AS
SELECT NAZWA_DANIA, CENA, DOSTÊPNOŒÆ
FROM DANIE
ORDER BY CENA ASC;

--3 przypadek u¿ycia bazy danych -----> £¹czenie 3 tabel
CREATE OR REPLACE VIEW perspektywa_3 AS
SELECT p.KWOTA, p.METODA_P£ATNOŒCI,r.status,r.id_klienta, re.iloœæ_osób,re.stoliki_id_stolika as id_stolika, s.NUMER_STOLIKA
FROM P³ATNOŒCI p
JOIN RACHUNKI r
ON(p.DATA_P£ATNOŒCI = r.DATA_ZAMÓWIENIA)
    JOIN REZERWACJE re
ON(p.DATA_P£ATNOŒCI = re.DATA_REZERWACJI)
    JOIN STOLIKI s
ON(re.STOLIKI_ID_STOLIKA = s.ID_STOLIKA);


--4 przypadek u¿ycia bazy danych------------------------------------------------
---Nieskorelowane

CREATE VIEW perspektywa_4 AS
SELECT NAZWA_DANIA
FROM DANIE
WHERE CENA >(SELECT CENA
            FROM DANIE
            WHERE ID_DANIA = 5);

---Skorelowane

CREATE VIEW perspektywa_5 AS
SELECT NAZWA_DANIA
FROM DANIE
WHERE CENA >(SELECT AVG(CENA)
            FROM DANIE);
--5 przypadek u¿ycia bazy danych ---->JEDNOWIERSZOWE

CREATE VIEW perspektywa_6 AS
SELECT ID_RACHUNKU, ID_KLIENTA, STATUS, TO_CHAR(DATA_ZAMÓWIENIA, 'YYYY/Mon/DD') AS DATA
FROM RACHUNKI
WHERE DATA_ZAMÓWIENIA < TO_DATE('2024/12/31', 'YYYY/MM/DD');

--GRUPOWA
CREATE OR REPLACE VIEW perspektywa_7 AS
SELECT MAX(CENA) AS NAJDROZSZE, MIN(CENA) AS NAJTANSZE, AVG(CENA) AS SREDNIA, SUM(cena) AS SUMA_CEN_DAN
FROM DANIE;

CREATE VIEW perspektywa_8 AS
SELECT NVL(TELEFON, 0) AS NUMER_LUB_ZERO
FROM KLIENCI;

CREATE OR REPLACE VIEW perspektywa_9 AS
SELECT UPPER(STATUS) AS CAPS
FROM REZERWACJE;

CREATE VIEW perspektywa_10 AS
SELECT ROUND(AVG(KWOTA), 2) AS ŒREDNIA_P£ATNOŒÆ
FROM P£ATNOŒCI;

