CREATE SEQUENCE numer_koszulki_seq
INCREMENT BY 1
START WITH 22
MAXVALUE 50
NOCACHE
NOCYCLE;

ALTER TABLE PRACOWNICY
ADD numer_koszulki_pilkarskiej NUMERIC(2);

ALTER TABLE PRACOWNICY
